#!/usr/bin/env python3
"""
KMVTECH Education - put the approved Research Methods Module 1 content into the pages.

Run from the root of the kmvtechug repository (after patch-lock-cards.py):
    python inject-resmeth-m1.py

It changes only education/courses/resmeth/ pages for Module 1:
  1/1/1 1/1/2 1/1/3 1/1/quiz   1/2/1 1/2/2 1/2/3 1/2/quiz   1/summary   1/quiz
and leaves the access check, progress tracking and score saving untouched.
Quiz fixes made at the same time:
  - correct answers are spread across the options (they were always the first one)
  - the question count is read from the page (it was fixed at 5 or 8)
  - practice quizzes show the right answer and feedback after checking
  - the graded quiz shows Passed / Below the 70% pass mark
Safe to run more than once.
"""
import os, re, sys, json, html

CONTENT = json.loads(r'''{"video":{"1/1/1":{"onpage":["**Key points from this video**","- Research is a planned, evidence-based investigation of a clear question, carried out in a way that others can check.","- Good research is systematic, empirical, open to checking, focused on a question, and ethical.","- Opinion is not research, and an internet search is only one part of research.","- Basic research builds understanding. Applied research tackles a practical problem. Many student projects are applied.","- Deductive reasoning tests an expectation. Inductive reasoning builds an explanation from patterns.","- A project moves through stages from topic to report, and you may return to earlier stages to refine them.","**Pause and reflect:** Think of a decision you made recently after finding information. Which of the five characteristics did your information gathering have? Which were missing?"]},"1/2/1":{"onpage":["**Key points from this video**","- The aim states the overall purpose of the study in one sentence and comes from the research question.","- Objectives are specific, measurable steps. Start each with an observable verb such as describe, measure, compare or identify.","- A hypothesis is a testable prediction about variables. H0 says no relationship. H1 states what you expect.","- Data support a hypothesis or fail to support it. They do not prove it.","- Qualitative studies usually use research questions instead of hypotheses.","- Keep a golden thread: question, aim, objectives, hypotheses and methods must match.","**Pause and reflect:** Rewrite this weak objective so it can be measured: To know about student savings."]}},"text":{"1/1/2":{"body":[["h","Why a question matters"],["p","A topic is an area of interest, such as mobile money. A research question is a focused, answerable question about that topic. The question matters because it decides what you read, whom you ask, what you measure and how you analyse (Booth et al., 2016). A project without a clear question tends to collect a lot of information and answer nothing."],["h","From a broad area to a question"],["p","Most good questions come from narrowing step by step. Think of a funnel: broad area, then topic, then focused problem, then research question. Here is the running example used in this course."],["t",["Step","Example"],[["Broad area","Personal finance"],["Topic","Mobile money use"],["Focused problem","Many boda boda riders in Kampala earn daily and may find it hard to save"],["Research question","How does the frequency of mobile money use relate to the savings of boda boda riders in Kampala?"]]],["h","Use who, what, where, when and how"],["p","These five prompts help you narrow the scope. Write a short answer to each."],["t",["Prompt","Example answer"],[["Who","Boda boda riders aged 18 to 40"],["What","Frequency of mobile money use and amount saved"],["Where","Selected stages in Kampala"],["When","The last 30 days"],["How","A short questionnaire (decided later in Module 2)"]]],["h","Types of research questions"],["b",["**Descriptive:** What mobile money services do boda boda riders in Kampala use?","**Relational or comparative:** Is there a relationship between mobile money use and savings? Do frequent users save more than occasional users?","**Explanatory or exploratory:** Why do some riders save while others do not? How do riders decide whether to save?"]],["h","Qualities of a good research question"],["b",["**Clear:** one idea, plain words.","**Focused:** limited by group, place and time.","**Researchable:** you can answer it with evidence, not only with opinion.","**Relevant:** it matters to a field, a community or a policy problem.","**Doable:** you can answer it with your time, money and skills (see Lesson 1.2).","**Ethical:** answering it does not harm participants."]],["h","Common mistakes"],["b",["**Too broad:** Why is Uganda poor?","**Opinion, not evidence:** Should boda boda be banned in Kampala? A researchable version: What do riders and commuters report about the safety and income effects of boda boda regulation?","**Yes or no:** Is mobile money good? A better version asks how or to what extent.","**Two questions in one:** split them into two questions."]],["box","Illustrative example","Weak: Education in Uganda. Better: What factors do first-year students at one Ugandan university report as the main reasons for missing lectures? The second version names the group, the place, the issue and the type of evidence."],["h","Key terms"],["b",["**Research topic:** a broad area of interest.","**Research problem:** a specific issue or gap that needs investigation.","**Research question:** a focused, answerable question that guides the study."]],["h","Check yourself"],["b",["Take a topic you care about. Write who, what, where, when and how for it.","Write one descriptive question and one relational question about the same topic."]]]},"1/1/3":{"body":[["h","What a literature review does"],["p","A literature review shows what is already known about your topic, where the gaps or disagreements are, and which concepts and methods earlier researchers used (Ridley, 2012). It stops you repeating work that has been done, and it gives you the evidence for your rationale, which is the argument for why your study is needed."],["h","Where to look"],["b",["**Peer-reviewed journal articles:** checked by other experts before publication.","**Books and book chapters:** useful for theory and background.","**Theses and dissertations:** often found in university libraries and repositories.","**Grey literature:** reports and statistics from government and agencies, for example the Uganda Bureau of Statistics, and reports from international organisations and NGOs. These are not journal articles, so check who produced them and how."]],["p","In Uganda, combine global theory with local studies. A study from another country can give you concepts and methods, but local studies tell you whether the situation is similar."],["h","How to search"],["p","Start by listing keywords and synonyms. Then combine them with Boolean operators. AND narrows the search because every term must appear. OR widens it because either term can appear. NOT excludes a term. Search phrases go in quotation marks, and an asterisk finds word endings."],["box","Example search string","(\"mobile money\" OR \"mobile banking\") AND (saving* OR \"savings behaviour\") AND Uganda"],["p","Free tools such as Google Scholar are a good start. Also use the databases your university library provides."],["h","Read critically and keep a matrix"],["p","For each source ask: Who wrote it, and when? What question did they ask? What method and sample did they use? What did they find? What are the limits? Record this in a literature matrix so that you can compare studies."],["t",["Source","Context","Method","Main finding","Gap or limit"],[["Study A (illustrative)","Urban traders","Survey","Higher use linked to higher saving","Not riders"],["Study B (illustrative)","Rural households","Interviews","Trust in agents affects use","Small sample"]]],["p","The entries above are placeholders to show the layout. They are not real studies."],["h","Finding the gap"],["b",["**Context gap:** not studied in your group or place.","**Method gap:** earlier studies used only one kind of method.","**Conflict:** studies disagree and the reason is unclear.","**Outdated evidence:** conditions have changed since the last study."]],["h","Writing the rationale"],["p","A rationale moves in five steps: the problem, what is known, the gap, why it matters, and what your study will do. A sentence frame: Although earlier studies show X, little is known about Y in Z, and this matters because W. This study therefore examines Y among Z."],["box","Illustrative rationale","Mobile money is widely used in Uganda, and studies in other settings link its use to saving. However, little is known about how often daily-income workers such as boda boda riders use it to save. This matters because irregular income makes saving difficult. This study therefore examines how the frequency of mobile money use relates to the savings of boda boda riders in Kampala."],["h","Cite and avoid plagiarism"],["p","Use the referencing style your department requires. APA 7th edition uses author and year in the text, for example (Bryman, 2016), and a full reference list at the end. Paraphrase in your own words and still cite the source, because changing the words does not remove the need to cite. Only cite sources you have actually read. If an AI tool suggests a reference, confirm that the source really exists before you use it."],["h","Key terms"],["b",["**Literature review:** a critical summary of earlier work on your topic.","**Gap:** something not yet known, studied or settled.","**Rationale:** the argument for why the study is needed.","**Grey literature:** reports and documents not published through journals."]],["h","Check yourself"],["b",["Write a search string with two synonyms for each of your main concepts.","Write a three-sentence rationale using the sentence frame."]]]},"1/2/2":{"body":[["h","What is a conceptual framework?"],["p","A conceptual framework is a map, in a diagram or in words, of the main concepts in your study and how you expect them to be related (Maxwell, 2013). It organises your thinking before fieldwork. It guides what you measure and how you analyse. It should fit your question, not decorate your proposal. Some departments separate a theoretical framework, which is built on an established theory, from a conceptual framework, which is your own map built from theory and the literature. Check your department guidelines."],["h","Variables"],["b",["**Independent variable:** the factor you expect to influence the outcome.","**Dependent variable:** the outcome you want to explain.","**Control variable:** another factor you measure so that you can take its effect into account.","**Moderating variable:** changes the strength of the relationship.","**Mediating variable:** helps explain how one variable affects another."]],["box","Running example","Independent variable: frequency of mobile money use. Dependent variable: amount saved. Control variables: age, daily income, years of riding."],["p","In words: Frequency of mobile money use  leads to  amount saved, while age, daily income and years of riding are controlled."],["h","Build your framework in five steps"],["n",["List the key concepts in your research question.","Define each concept in plain words.","Decide how each concept will be measured. This is the operational definition.","Draw arrows for the relationships you expect, using the literature.","Check that every concept in the diagram appears in your question or objectives."]],["box","Operational definition (illustrative)","Savings amount: the total amount in UGX that a rider reports setting aside in the last 30 days, whether in a mobile money wallet, a savings group or at home."],["h","Frameworks in qualitative studies"],["p","Qualitative studies often use broad concepts to guide data collection. These concepts may be refined as themes appear in the data. The framework may look like a list or map of ideas rather than variables with arrows."],["h","Common mistakes"],["b",["Too many boxes and arrows, so the diagram shows everything and explains nothing.","Concepts that you cannot measure or observe.","A framework that does not match the question or objectives.","No link to the literature."]],["h","Key terms"],["b",["**Concept:** an idea that you study, such as saving.","**Variable:** a concept that can take different values.","**Operational definition:** how a variable is measured in your study."]],["h","Check yourself"],["b",["Draw a framework for your own research question with one independent variable, one dependent variable and two control variables.","Write an operational definition for each variable."]]]},"1/2/3":{"body":[["h","Why feasibility matters"],["p","A good idea is not enough. A study must also be possible within your limits. A smaller study done well is better than an ambitious study that is never finished (Saunders et al., 2019). Check feasibility before you commit to a design."],["h","What limits a student project"],["b",["**Time:** semester deadlines and the time to get permissions.","**Money:** transport, airtime or data, printing and any fees.","**Access:** can you reach the people or records you need? You may need permission from an institution or local leaders.","**Skills:** can you use the method and the analysis you plan to use?","**Language:** can you collect data in the languages your participants use?","**Data:** do the records or statistics you need exist and can you see them?","**Ethics:** studies with people usually need ethics review and permissions."]],["box","A note on ethics approval in Uganda","Many studies with human participants need approval from an institutional research ethics committee and, depending on the study, registration with the Uganda National Council for Science and Technology (UNCST). Module 6 covers research ethics. Ask your supervisor which rules apply to your project."],["h","Scope: set clear boundaries"],["p","Scope is the boundary of your study: which people, which place, which time period and which variables. Write the boundaries down."],["b",["**Delimitations** are choices you make to narrow the study. Example: only riders at selected stages in two divisions of Kampala.","**Limitations** are weaknesses you cannot fully control. Example: riders may not remember exactly how much they saved."]],["h","A quick feasibility checklist"],["t",["Question","Yes or No"],[["Can I finish within the time I have?",""],["Can I afford the costs?",""],["Can I reach enough participants or records?",""],["Do I have the skills for the method and analysis?",""],["Can I collect data in a language participants use?",""],["Do I know what permissions and ethics approval I need?",""]]],["p","If you answer No to any item, change the scope, the sample or the method before you continue. Talk to your supervisor and test your plan with a few people first."],["h","Worked example: reducing the scope"],["t",["Too big","Scoped down"],[["All boda boda riders in Uganda","Riders at selected stages in two Kampala divisions"],["Over three years","Over the last 30 days"],["Many variables","Mobile money frequency, savings, and three control variables"]]],["h","Key terms"],["b",["**Feasibility:** whether the study can be completed with your time, money, access and skills.","**Scope:** the boundaries of the study.","**Delimitation:** a deliberate choice that narrows the study.","**Limitation:** a weakness outside the researcher's full control."]],["h","Check yourself"],["b",["Complete the checklist for your own project and name the one item that worries you most.","Write one delimitation and one limitation for your project."]]]}},"quiz":{"1/1/quiz":{"fb":true,"qs":[{"q":"Which statement best describes research?","o":["Collecting opinions from friends","Finding quotations that agree with your idea","A planned, evidence-based investigation of a clear question","Reading a few online posts"],"a":"C","f":"Research is systematic and evidence-based, and it answers a clear question in a way others can check."},{"q":"True or False: Basic research aims mainly to solve an immediate practical problem.","tf":true,"a":"False","f":"That describes applied research. Basic research aims to expand understanding."},{"q":"Which is the most researchable question?","o":["How does the frequency of mobile money use relate to the monthly savings of boda boda riders in Kampala?","Should boda boda be banned in Kampala?","Why is Uganda poor?","Mobile money"],"a":"A","f":"It names the group, the place and the variables, and it can be answered with evidence."},{"q":"Which Boolean operator widens a search by allowing either of two synonyms?","o":["AND","NOT","TO","OR"],"a":"D","f":"OR widens a search. AND narrows it. NOT excludes a term."},{"q":"True or False: A literature review should include only sources that agree with your idea.","tf":true,"a":"False","f":"A review should be balanced and should show disagreements and gaps as well."},{"q":"A student finds that many studies exist in cities but none in one rural district. This is mainly a:","o":["Plagiarism problem","Context gap","Sampling error","Hypothesis"],"a":"B","f":"A context gap means the topic has not been studied in your group or place."}]},"1/2/quiz":{"fb":true,"qs":[{"q":"Which objective is best written?","o":["To understand mobile money","To appreciate savings","To measure how often riders save through mobile money","To know about riders"],"a":"C","f":"It uses an observable verb and can be checked at the end of the study."},{"q":"True or False: One study can prove a hypothesis beyond doubt.","tf":true,"a":"False","f":"Data support a hypothesis or fail to support it. We do not say it is proven."},{"q":"In the framework frequency of mobile money use leads to amount saved, the amount saved is the:","o":["Dependent variable","Independent variable","Control variable","Null hypothesis"],"a":"A","f":"The dependent variable is the outcome you want to explain."},{"q":"Age is measured so that its effect can be taken into account. Age is a:","o":["Aim","Delimitation","Rationale","Control variable"],"a":"D","f":"A control variable is measured so that its effect can be accounted for."},{"q":"True or False: Limitations are the choices a researcher makes to narrow the study.","tf":true,"a":"False","f":"Those are delimitations. Limitations are weaknesses outside your full control."},{"q":"A supervisor says: you plan to study 20 districts in 3 months with no transport budget. The main problem is:","o":["The research question is unethical","Feasibility and scope","The hypothesis is null","The literature review is too short"],"a":"B","f":"The study is too large for the time and money. Narrow the scope or the sample."}]},"1/quiz":{"fb":false,"qs":[{"q":"Which is NOT a characteristic of good research?","o":["Systematic","Empirical","Based only on opinion","Open to checking"],"a":"C","f":"Research relies on evidence, not opinion alone."},{"q":"Applied research is best described as research that:","o":["Aims to address a practical problem","Has no link to theory","Uses no data","Is done only in laboratories"],"a":"A","f":"Applied research tackles a practical problem."},{"q":"A student starts with a theory, states what she expects, and collects data to test it. This is:","o":["Inductive reasoning","Plagiarism","Piloting","Deductive reasoning"],"a":"D","f":"Deductive reasoning starts from theory and tests expectations with data."},{"q":"A researcher notices patterns across interviews and builds an explanation from them. This is:","o":["Deductive reasoning","Inductive reasoning","A null hypothesis","A control variable"],"a":"B","f":"Inductive reasoning builds explanations from observed patterns."},{"q":"True or False: A research topic and a research question are the same thing.","tf":true,"a":"False","f":"A topic is a broad area. A question is focused and answerable."},{"q":"Which question is descriptive?","o":["Do frequent users save more than occasional users?","Why do some riders save while others do not?","Should mobile money be taxed?","What mobile money services do boda boda riders in Kampala use?"],"a":"D","f":"A descriptive question asks what something is or what exists."},{"q":"What is the main weakness of the question: Why is education in Uganda poor?","o":["It is too broad","It is too narrow","It is a yes or no question","It has a null hypothesis"],"a":"A","f":"It does not name a group, place, time or specific issue."},{"q":"What is the correct order for narrowing a topic?","o":["Question, problem, topic, broad area","Topic, question, broad area, problem","Broad area, topic, focused problem, research question","Problem, broad area, question, topic"],"a":"C","f":"Think of a funnel that narrows step by step."},{"q":"In a search string, what does AND do?","o":["Widens the search","Narrows the search by requiring all terms","Excludes a term","Finds only journal articles"],"a":"B","f":"AND requires every term to appear in the result."},{"q":"Which is an example of grey literature?","o":["A government or agency report not published in a journal","A peer-reviewed journal article","A textbook chapter","A newspaper opinion column"],"a":"A","f":"Grey literature includes reports and documents not published through journals. Always check who produced them."},{"q":"Choosing to study only riders at selected stages in two Kampala divisions is a:","o":["Limitation","Hypothesis","Gap","Delimitation"],"a":"D","f":"A delimitation is a deliberate choice that narrows the study."},{"q":"The purpose of a rationale is to:","o":["List the data collection tools","Explain why the study is needed using what is known and the gap","Present the results","Define the variables"],"a":"B","f":"A rationale argues that the study is needed, using the problem, the literature and the gap."},{"q":"True or False: Paraphrasing a source without citing it is acceptable if you change the words.","tf":true,"a":"False","f":"Ideas must still be cited. Not citing paraphrased ideas is plagiarism."},{"q":"Which statement about aims and objectives is correct?","o":["Objectives state the overall purpose and the aim lists the steps","They mean the same thing","The aim states the overall purpose and objectives break it into specific steps","Objectives are only used in qualitative studies"],"a":"C","f":"One aim states the purpose. Objectives are the specific steps to reach it."},{"q":"Which objective uses a measurable verb?","o":["To appreciate mobile money","To understand savings","To compare savings between frequent and occasional users","To look at riders"],"a":"C","f":"Compare is observable and can be checked."},{"q":"Which is a directional hypothesis?","o":["Riders who use mobile money more often save more","There is no relationship between use and savings","There is a relationship between use and savings","Mobile money is useful"],"a":"A","f":"A directional hypothesis states the direction of the relationship."},{"q":"The null hypothesis (H0) states that:","o":["There is a strong relationship","The study is unethical","The sample is too small","There is no relationship or difference"],"a":"D","f":"H0 states that there is no relationship or no difference."},{"q":"True or False: Qualitative studies usually test formal hypotheses with statistics.","tf":true,"a":"False","f":"Qualitative studies usually use research questions rather than statistical hypotheses."},{"q":"A student's framework has 15 variables with arrows between most of them, but the question is about two variables. The best advice is to:","o":["Add more variables","Simplify the framework to the concepts that match the question","Remove the question","Delete the literature review"],"a":"B","f":"A framework should fit the question and be measurable."},{"q":"A researcher plans 300 interviews in 10 districts in 6 weeks with no transport money. The best response is to:","o":["Proceed and hope","Skip ethics approval","Use only opinion","Narrow the scope, for example fewer districts or a smaller sample, or change the method"],"a":"D","f":"If the plan is not feasible, change the scope, sample or method before starting."}]}},"summary":{"points":["Research is a planned, evidence-based investigation of a clear question that others can check.","Good research is systematic, empirical, open to checking, focused and ethical.","Basic research builds understanding. Applied research tackles practical problems. Deductive reasoning tests expectations. Inductive reasoning builds explanations.","Narrow a topic into a question using who, what, where, when and how. A good question is clear, focused, researchable, relevant, doable and ethical.","A literature review shows what is known and where the gaps are. A rationale argues why the study is needed. Cite what you use.","The aim gives the overall purpose. Objectives are specific and measurable. Hypotheses are testable predictions, and data support them or fail to support them.","A conceptual framework maps the concepts and expected relationships. Check feasibility and set the scope before you start."],"terms":[["Research","Planned, evidence-based investigation of a clear question"],["Research question","A focused, answerable question that guides the study"],["Literature review","A critical summary of earlier work"],["Gap","Something not yet known, studied or settled"],["Rationale","The argument for why the study is needed"],["Aim","The overall purpose of the study"],["Objective","A specific, measurable step to reach the aim"],["Hypothesis","A testable prediction about variables"],["Variable","A concept that can take different values"],["Operational definition","How a variable is measured"],["Delimitation / Limitation","A choice that narrows the study / a weakness outside your control"],["Feasibility","Whether the study can be completed with your time, money, access and skills"]]}}''')
HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = next((p for p in (HERE, os.getcwd()) if os.path.isdir(os.path.join(p, 'education', 'courses'))), None)
if ROOT is None:
    print('ERROR: I cannot find the "education" folder.')
